<?php
require __DIR__.'/../includes/ui.php';requireRole(['admin']);$error='';$date=(string)($_GET['tanggal']??date('Y-m-d'));
if($_SERVER['REQUEST_METHOD']==='POST')try{
 need(validDate($date)&&$date<=date('Y-m-d'),'Tanggal tidak valid.');$data=$_POST['presensi']??[];need(is_array($data)&&count($data)>0,'Pilih minimal satu status.');getDB()->begin_transaction();$saved=0;
 foreach($data as $id=>$status){if($status==='')continue;need(in_array($status,['hadir','izin','sakit','alpa'],true),'Status tidak valid.');need((bool)dbOne("SELECT id FROM guru WHERE id=? AND status='aktif'",[(int)$id]),'Guru tidak aktif.');dbRun("INSERT INTO absensi_guru (guru_id,tanggal,status,jam_masuk,keterangan) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),jam_masuk=IF(VALUES(status)='hadir',COALESCE(jam_masuk,VALUES(jam_masuk)),NULL),keterangan=VALUES(keterangan)",[(int)$id,$date,$status,$status==='hadir'&&$date===date('Y-m-d')?date('H:i:s'):null,substr((string)($_POST['keterangan'][$id]??''),0,1000)]);$saved++;}
 need($saved>0,'Pilih minimal satu status.');getDB()->commit();flash('Presensi guru berhasil disimpan.');header('Location: ?tanggal='.urlencode($date));exit;
}catch(Throwable $ex){getDB()->rollback();$error=actionError($ex);}
pageStart('Absensi Guru','Catat kehadiran guru untuk laporan kepala sekolah.');if($error)echo '<div class="message error">'.e($error).'</div>';filterForm(['tanggal'=>['Tanggal','date',$date]]);
$teachers=dbAll("SELECT g.*,a.status presensi,a.keterangan FROM guru g LEFT JOIN absensi_guru a ON a.guru_id=g.id AND a.tanggal=? WHERE g.status='aktif' ORDER BY g.nama",[$date]);?>
<form method="post"><?=csrfField()?><div class="table-wrapper"><table><thead><tr><th>Guru</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><?php foreach($teachers as $g):?><tr><td><?=e($g['nama'])?></td><td><?php selectField('presensi['.$g['id'].']','Status '.$g['nama'],['hadir'=>'Hadir','izin'=>'Izin','sakit'=>'Sakit','alpa'=>'Alpa'],$g['presensi'],false);?></td><td><input name="keterangan[<?=$g['id']?>]" aria-label="Keterangan <?=e($g['nama'])?>" value="<?=e($g['keterangan'])?>"></td></tr><?php endforeach;?></tbody></table></div><div class="form-actions"><button class="btn">Simpan Presensi Guru</button></div></form><?php pageEnd();
